import { useState } from "react";
import { login, register, getMe, verifyOTP, resendOTP } from "../services/api";
import { G } from "../App";

export default function Login({ onLogin }) {
  const [mode, setMode]       = useState("login");
  const [form, setForm]       = useState({ name: "", email: "", password: "" });
  const [otp, setOtp]         = useState("");
  const [msg, setMsg]         = useState("");
  const [loading, setLoading] = useState(false);
  const [resendCooldown, setResendCooldown] = useState(0);

  const isSuccess = (m) => typeof m === "string" && m.startsWith("✅");
  const set = (k) => (e) => setForm(f => ({ ...f, [k]: e.target.value }));

  const handleRegister = async () => {
    if (!form.name || !form.email || !form.password) { setMsg("Please fill all fields."); return; }
    setMsg(""); setLoading(true);
    try {
      await register({ name: form.name, email: form.email, password: form.password });
      setMsg("✅ OTP sent to your email! Check your inbox.");
      setMode("verify-otp");
    } catch (e) { const d = e.response?.data?.detail; setMsg(typeof d === 'string' ? d : Array.isArray(d) ? d[0]?.msg || 'Registration failed.' : 'Registration failed.'); }
    setLoading(false);
  };

  const handleVerifyOTP = async () => {
    if (otp.length !== 6) { setMsg("Please enter the 6-digit OTP."); return; }
    setMsg(""); setLoading(true);
    try {
      await verifyOTP({ email: form.email, otp });
      setMsg("✅ Email verified! You can now log in.");
      setMode("login"); setOtp("");
    } catch (e) { const d = e.response?.data?.detail; setMsg(typeof d === 'string' ? d : 'Invalid OTP.'); }
    setLoading(false);
  };

  const handleResend = async () => {
    if (resendCooldown > 0) return;
    setMsg(""); setLoading(true);
    try {
      await resendOTP({ email: form.email });
      setMsg("✅ New OTP sent!");
      setResendCooldown(30);
      const t = setInterval(() => setResendCooldown(c => { if (c <= 1) { clearInterval(t); return 0; } return c - 1; }), 1000);
    } catch (e) { const d = e.response?.data?.detail; setMsg(typeof d === 'string' ? d : 'Failed to resend.'); }
    setLoading(false);
  };

  const handleLogin = async () => {
    if (!form.email || !form.password) { setMsg("Please fill all fields."); return; }
    setMsg(""); setLoading(true);
    try {
      const res = await login({ email: form.email, password: form.password });
      localStorage.setItem("token", res.data.access_token);
      const me = await getMe();
      onLogin(me.data, res.data.access_token);
    } catch (e) { const d = e.response?.data?.detail; setMsg(typeof d === 'string' ? d : Array.isArray(d) ? d[0]?.msg || 'Login failed.' : 'Login failed.'); }
    setLoading(false);
  };

  const s = {
    page: {
      minHeight: "100vh",
      background: "linear-gradient(135deg, #eff6ff 0%, #dbeafe 50%, #eff6ff 100%)",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      fontFamily: G.font,
    },
    card: {
      background: "#ffffff",
      borderRadius: 20,
      padding: "44px 48px",
      width: 420,
      boxShadow: "0 20px 60px rgba(37,99,235,0.12), 0 4px 16px rgba(37,99,235,0.08)",
      border: "1px solid #dbeafe",
    },
    topBar: {
      height: 4,
      background: "linear-gradient(90deg, #2563eb, #1d4ed8, #3b82f6)",
      borderRadius: "20px 20px 0 0",
      margin: "-44px -48px 36px",
    },
    logoArea: {
      textAlign: "center",
      marginBottom: 32,
    },
    logoIcon: { fontSize: 40, marginBottom: 10 },
    logoText: {
      fontWeight: 900,
      fontSize: 28,
      color: "#1e3a8a",
      letterSpacing: "-1px",
    },
    logoSub: {
      color: G.muted,
      fontSize: 13,
      marginTop: 4,
    },
    label: {
      fontSize: 11,
      color: G.muted,
      letterSpacing: 1.5,
      textTransform: "uppercase",
      fontWeight: 700,
      marginBottom: 6,
      display: "block",
    },
    input: {
      width: "100%",
      background: "#f8faff",
      border: "1.5px solid #dbeafe",
      borderRadius: 10,
      padding: "12px 14px",
      color: G.text,
      fontSize: 14,
      fontFamily: G.font,
      marginBottom: 16,
      transition: "border 0.2s",
    },
    otpInput: {
      width: "100%",
      background: "#f8faff",
      border: "2px solid #2563eb",
      borderRadius: 10,
      padding: "16px 14px",
      color: "#1e3a8a",
      fontSize: 32,
      fontFamily: "'JetBrains Mono', monospace",
      marginBottom: 16,
      textAlign: "center",
      letterSpacing: 14,
      fontWeight: 700,
    },
    btn: {
      width: "100%",
      padding: "13px",
      background: "linear-gradient(135deg, #2563eb, #1d4ed8)",
      border: "none",
      borderRadius: 10,
      color: "#fff",
      fontWeight: 700,
      fontSize: 14,
      cursor: loading ? "wait" : "pointer",
      fontFamily: G.font,
      marginTop: 4,
      letterSpacing: 0.3,
      boxShadow: "0 4px 14px rgba(37,99,235,0.3)",
    },
    toggle: {
      textAlign: "center",
      marginTop: 20,
      fontSize: 13,
      color: G.muted,
    },
    toggleLink: {
      color: "#2563eb",
      cursor: "pointer",
      fontWeight: 700,
      marginLeft: 4,
    },
    msgBox: {
      background: isSuccess(msg) ? "#f0fdf4" : "#fef2f2",
      border: `1px solid ${isSuccess(msg) ? "#bbf7d0" : "#fecaca"}`,
      borderRadius: 8,
      padding: "10px 14px",
      fontSize: 13,
      color: isSuccess(msg) ? "#16a34a" : "#dc2626",
      marginBottom: 16,
    },
    emailBadge: {
      background: "#eff6ff",
      border: "1px solid #bfdbfe",
      borderRadius: 8,
      padding: "10px 14px",
      fontSize: 13,
      color: "#2563eb",
      marginBottom: 18,
      textAlign: "center",
      fontWeight: 500,
    },
    resendBtn: {
      background: "none",
      border: "none",
      color: resendCooldown > 0 ? G.muted : "#2563eb",
      cursor: resendCooldown > 0 ? "default" : "pointer",
      fontSize: 13,
      fontFamily: G.font,
      fontWeight: 700,
      padding: 0,
    },
  };

  return (
    <div style={s.page}>
      <div style={s.card} className="fade-in">
        <div style={s.topBar} />
        <div style={s.logoArea}>
          <div style={s.logoIcon}>💸</div>
          <div style={s.logoText}>ExpenseIQ</div>
          <div style={s.logoSub}>
            {mode === "login" ? "Sign in to your account" : mode === "register" ? "Create your account" : "Verify your email"}
          </div>
        </div>

        {msg && <div style={s.msgBox}>{msg}</div>}

        {/* OTP Verify */}
        {mode === "verify-otp" && (
          <>
            <div style={s.emailBadge}>📧 OTP sent to {form.email}</div>
            <label style={s.label}>Enter 6-Digit Code</label>
            <input style={s.otpInput} type="text" maxLength={6} placeholder="000000"
              value={otp} onChange={e => setOtp(e.target.value.replace(/\D/g, ""))}
              onKeyDown={e => e.key === "Enter" && handleVerifyOTP()} />
            <button style={s.btn} onClick={handleVerifyOTP} disabled={loading}>
              {loading ? "Verifying..." : "Verify OTP"}
            </button>
            <div style={{ textAlign: "center", marginTop: 16, fontSize: 13, color: G.muted }}>
              Didn't receive it?{" "}
              <button style={s.resendBtn} onClick={handleResend} disabled={loading || resendCooldown > 0}>
                {resendCooldown > 0 ? `Resend in ${resendCooldown}s` : "Resend OTP"}
              </button>
            </div>
            <div style={s.toggle}>
              <span style={s.toggleLink} onClick={() => { setMode("register"); setMsg(""); setOtp(""); }}>← Back</span>
            </div>
          </>
        )}

        {/* Register */}
        {mode === "register" && (
          <>
            <label style={s.label}>Full Name</label>
            <input style={s.input} placeholder="Vighnesh Nadar" value={form.name} onChange={set("name")} onKeyDown={e => e.key === "Enter" && handleRegister()} />
            <label style={s.label}>Email Address</label>
            <input style={s.input} type="email" placeholder="you@email.com" value={form.email} onChange={set("email")} onKeyDown={e => e.key === "Enter" && handleRegister()} />
            <label style={s.label}>Password</label>
            <input style={s.input} type="password" placeholder="Minimum 8 characters" value={form.password} onChange={set("password")} onKeyDown={e => e.key === "Enter" && handleRegister()} />
            <button style={s.btn} onClick={handleRegister} disabled={loading}>
              {loading ? "Sending OTP..." : "Create Account"}
            </button>
            <div style={s.toggle}>
              Already have an account?
              <span style={s.toggleLink} onClick={() => { setMode("login"); setMsg(""); }}>Sign In</span>
            </div>
          </>
        )}

        {/* Login */}
        {mode === "login" && (
          <>
            <label style={s.label}>Email Address</label>
            <input style={s.input} type="email" placeholder="you@email.com" value={form.email} onChange={set("email")} onKeyDown={e => e.key === "Enter" && handleLogin()} />
            <label style={s.label}>Password</label>
            <input style={s.input} type="password" placeholder="••••••••" value={form.password} onChange={set("password")} onKeyDown={e => e.key === "Enter" && handleLogin()} />
            <button style={s.btn} onClick={handleLogin} disabled={loading}>
              {loading ? "Signing in..." : "Sign In"}
            </button>
            <div style={s.toggle}>
              Don't have an account?
              <span style={s.toggleLink} onClick={() => { setMode("register"); setMsg(""); }}>Register</span>
            </div>
          </>
        )}
      </div>
    </div>
  );
}
